void rf_loop_init (void)
{
	cmd_lut_insert(INPUT_GWR_OFF	, rf_loop_pwr_clr		, (Exec_Mode)(EXEC_MODE_NORMAL | EXEC_MODE_PROG));
	cmd_lut_insert(INPUT_GWR_ON     , rf_loop_pwr_set  		, (Exec_Mode)(EXEC_MODE_NORMAL | EXEC_MODE_PROG));
 	
}

